parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "genuineOpportunity": {
      "type": "boolean",
      "description": "True only if this email describes a specific, real internship/job/placement opportunity with an identifiable company and a role or application process. False for generic circulars, reminders, event announcements, result declarations, or anything without an actual hiring opportunity."
    },
    "company": {
      "type": ["string", "null"],
      "description": "The hiring company or organization name. Null if not clearly stated."
    },
    "role": {
      "type": ["string", "null"],
      "description": "The job title or internship role, e.g. 'Software Developer Intern'. Null if not stated."
    },
    "opportunityType": {
      "type": ["string", "null"],
      "description": "One of: Internship, Full-Time Job, Internship with PPO, Trainee Program, or null if unclear."
    },
    "location": {
      "type": ["string", "null"],
      "description": "Work location city/state, or 'Remote' if explicitly remote. Null if not mentioned."
    },
    "eligibility": {
      "type": ["string", "null"],
      "description": "Eligible degree/branch/batch/CGPA criteria exactly as stated. Null if not mentioned."
    },
    "salaryOrStipend": {
      "type": ["string", "null"],
      "description": "Stipend, salary, or CTC figures exactly as stated, including currency. Null if not mentioned."
    },
    "deadline": {
      "type": ["string", "null"],
      "description": "Application deadline in YYYY-MM-DD format if a date is stated. Null if no deadline is mentioned."
    },
    "applicationLink": {
      "type": ["string", "null"],
      "description": "The direct URL to apply or register (form link, portal link, or careers page). Null if no link is present."
    },
    "description": {
      "type": ["string", "null"],
      "description": "A short 1-2 sentence neutral summary of the role, written by you, not copied verbatim from the email."
    }
  },
  "required": ["genuineOpportunity"]
}

parameters.jsCode:
// Pull the unique Gmail message ID from the original trigger
const messageId = $('Gmail Trigger').first().json.id;

// Pull the fields the AI extracted earlier in this chain
const extracted = $('Information Extractor').first().json.output;

// This node's own input = the HTTP Request node's response (the existing internships list)
const existingInternships = $input.first().json.internships || [];

// Check if this exact email was already ingested before
const isDuplicate = existingInternships.some(
  (item) => item.sourceMessageId === messageId
);

return [
  {
    json: {
      ...extracted,
      sourceMessageId: messageId,
      isDuplicate,
    },
  },
];
